class Solution {
public:
 int minTrioDegree(int n,vector<vector<int>>& edges){
  vector<vector<char>> adj(n+1,vector<char>(n+1));vector<int> deg(n+1);
  for(auto& e:edges){int a=e[0],b=e[1];adj[a][b]=adj[b][a]=1;++deg[a];++deg[b];}
  int ans=INT_MAX;
  for(int a=1;a<=n;++a)for(int b=a+1;b<=n;++b)if(adj[a][b])
   for(int c=b+1;c<=n;++c)if(adj[a][c]&&adj[b][c])ans=min(ans,deg[a]+deg[b]+deg[c]-6);
  return ans==INT_MAX?-1:ans;
 }
};
